<body>
  <canvas id="liquid-bg"></canvas>
  <div id="app-root"></div>

  <script>
    // --- PWA install prompt support
    let deferredPrompt;
    window.addEventListener('beforeinstallprompt', e => {
      e.preventDefault();
      deferredPrompt=e;
    });

    // --- Theme switcher
    function setTheme(t){
      document.documentElement.setAttribute('data-theme', t);
      localStorage.setItem('theme',t);
    }
    (()=>{let theme=localStorage.getItem('theme')||((window.matchMedia('(prefers-color-scheme: dark)').matches)?'dark':'light');setTheme(theme);})();

    // --- Dynamic background: animated gradients + bouncing blobs
    function drawLiquidBG() {
      const ctx = liquidBg.getContext('2d');
      const w = window.innerWidth, h = window.innerHeight;
      ctx.clearRect(0,0,w,h);
      // Animated gradient blobs:
      let t = performance.now()/750, cx = w/2, cy = h/2, r = h/1.3;
      for (let i=0; i<5; i++) {
        let angle = t + i * 1.32, rx = cx + Math.sin(angle) * r * .43, ry = cy + Math.cos(angle/1.7) * r * .31;
        let grad = ctx.createRadialGradient(rx,ry,70,rx,ry,240);
        grad.addColorStop(0,["#2fffa5","#21b5fa","#fd48ae","#ffed54","#13ffce"][i%5]);
        grad.addColorStop(1,"transparent");
        ctx.globalAlpha=0.33;
        ctx.beginPath(); ctx.arc(rx,ry,220+40*Math.sin(angle*0.91),0,Math.PI*2); ctx.closePath();
        ctx.fillStyle=grad; ctx.fill();
      }
      ctx.globalAlpha=1;
      requestAnimationFrame(drawLiquidBG);
    }
    const liquidBg = document.getElementById('liquid-bg');
    liquidBg.width = window.innerWidth, liquidBg.height = window.innerHeight;
    window.addEventListener('resize',()=>{liquidBg.width=window.innerWidth;liquidBg.height=window.innerHeight;});
    drawLiquidBG();

    // --- MAIN APP LOGIC + UI
    const root = document.getElementById('app-root');
    let conversations = JSON.parse(localStorage.getItem('jade_chats')||'[]'), currentConv = null;
    let proEnabled = false, showSidebar = false, plusMenuVisible = false, isResearching = false, researchProgress = 0, researchEst = 0, researchTitle = "", researchReport = "";
    let chatHistory = [];
    // --- UI Rendering
    function render() {
      root.innerHTML=`
        <div class="topbar ${proEnabled?'pro-on':''}">
          <button class="menu-btn" onclick="toggleSidebar()"><svg fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><rect y="4" width="24" height="2" rx="1"/><rect y="11" width="24" height="2" rx="1"/><rect y="18" width="24" height="2" rx="1"/></svg></button>
          <div class="jade-ai-label neon-gradient" onclick="toggleProMode()">${proEnabled?"Jade AI <span style='font-size:1.0rem;'>PRO</span>":"Jade AI"}</div>
          <button class="newchat-btn" onclick="startNewChat()">Új beszélgetés</button>
        </div>
        <div style="display:flex;justify-content:center;">
          <div class="chat-area">
            ${chatHistory.map(m=>`<div class="chat-message ${m.role==='jade'?'jade':'user'} glass">${m.content.replace(/\n/g,"<br>")}${m.elapsed?`<span class="chat-time">[${m.elapsed}]</span>`:""}</div>`).join("")}
            ${ isResearching ? renderResearchWidget():"" }
          </div>
        </div>
        <div class="input-bar-wrap" style="left:${showSidebar?'310px':'0'};">
          <div class="input-bar glass" style="position:relative">
            <button class="plus-btn" onclick="showPlusMenu(event)">+</button>
            <textarea id="chat-input" rows="1" placeholder="Írj ide..." onkeydown="if(event.key==='Enter'&&!event.shiftKey){sendMsg();return false;}"></textarea>
            <button class="send-btn" onclick="sendMsg()">&#10148;</button>
            ${plusMenuVisible?renderPlusMenu():''}
          </div>
        </div>
        <div class="sidebar ${showSidebar?'open':''}" onclick="if(event.target===this)toggleSidebar()">
          <div class="sidebar-content glass-dark" onclick="event.stopPropagation()">
            <input class="sidebar-search" type="text" placeholder="Keresés korábbi beszélgetések között" oninput="searchChat(this.value)">
            <div class="sidebar-chats">${conversations.map(c=>`<div class="sidebar-chat" onclick="loadChat('${c.id}')">${c.title}</div>`).join("")}</div>
            <div class="sidebar-bottom">
              <button class="profile-btn">&#128100;</button>
              <button class="settings-btn" onclick="toggleTheme()">${getTheme()=="dark"?"🌞":"🌜"}</button>
            </div>
          </div>
        </div>
        <div class="fullscreen-modal" id="report-modal">
          <div class="modal-content">${researchTitle?"<h2>"+researchTitle+"</h2>":""}<div>${researchReport.replace(/\n/g,"<br>")}</div>
            <div style="margin-top:2.5rem;text-align:right;"> <button onclick="closeReport()" style="padding:6px 22px;font-size:1rem;border:none;background:var(--jade-glass);border-radius:9px;">Bezár</button></div>
          </div>
        </div>
      `;
      if(proEnabled) document.querySelector('.jade-ai-label').innerHTML = "Jade AI <span style='font-size:1.0rem;'>PRO</span>";
      // iOS style haptic: tap
      document.querySelectorAll('button, .sidebar-chat, .pmenu-item').forEach(el=>el.addEventListener('touchstart', ()=>window.navigator.vibrate&&window.navigator.vibrate(8), {passive:true}));
    }

    // --- supporting UI fns
    function showPlusMenu(ev){
      plusMenuVisible = true;
      render();
      setTimeout(()=>{document.addEventListener('click', hidePlusMenu)},1);
    }
    function hidePlusMenu(){plusMenuVisible=false;render(); document.removeEventListener('click', hidePlusMenu);}
    function renderPlusMenu() {
      return `<div class="plus-menu glass" style="position:absolute;z-index:55;top:60px;left:-10px;">
        <div class="pmenu-item" onclick="setExtended()">🔍 Kibővített indoklás</div>
        <div class="pmenu-item" onclick="setResearch()">🧪 Mély kutatás</div>
        <div class="pmenu-item" onclick="setImageGen()">🎨 Kép generálás</div>
        <div class="pmenu-item" onclick="setWebsearch()">🌐 Web keresés</div>
        <div class="pmenu-item" onclick="setAttach()">📎 Fájl csatolás</div>
      </div>`;
    }
    function renderResearchWidget() {
      let w = Math.floor(researchProgress*100); let left=(researchEst-researchProgress).toFixed(1);
      return `<div class="research-widget glass">
        <div><b>Mély kutatás zajlik...</b><span class="doc-icon">${researchProgress>=1?`📄`:""}</span></div>
        <div class="research-progress-bar"><span class="research-progress" style="width:${w}%;"></span></div>
        <div class="research-stats">
          <span>Előrehaladás: ${w}%</span>
          <span>Idő: ${Math.floor(researchProgress*researchEst)}mp / ${researchEst}mp</span>
          <button style="padding:3px 12px;" onclick="showReport()" ${researchProgress>=1?'':'disabled'}>Riport megnyitása</button>
        </div>
      </div>`;
    }
    function toggleSidebar(){showSidebar=!showSidebar;render();}
    function toggleTheme(){ let t = getTheme()=="light"?"dark":"light"; setTheme(t); render();}
    function getTheme(){ return document.documentElement.getAttribute('data-theme'); }
    function toggleProMode(){proEnabled=!proEnabled;render();}
    function startNewChat(){chatHistory=[];currentConv=null;render();}
    function searchChat(v){ /* bevezetéssel, magyar nevű mezőkkel*/ }
    function setExtended(){alert("A funkció fejlesztés alatt áll.");}
    function setImageGen(){alert("A funkció fejlesztés alatt áll.");}
    function setWebsearch(){alert("A funkció fejlesztés alatt áll.");}
    function setAttach(){alert("A funkció fejlesztés alatt áll.");}
    function loadChat(id){let c=conversations.find(x=>x.id==id);if(c){chatHistory=c.history;currentConv=c.id;render();}}
    function setResearch() {
      isResearching=true;researchProgress=0;researchEst=22+Math.random()*5;researchTitle="Mély kutatási riport";
      render();
      // Szimulált deep-research, valós workflow-t backenddel végeztess!
      let step=0,stepCount=23+Math.floor(Math.random()*7),progress=()=>{step++;researchProgress=step/stepCount;render();
        if(step<stepCount) setTimeout(progress,245+Math.random()*190); else doneResearch();
      }; progress();
    }
    function doneResearch(){
      isResearching=false;researchProgress=1;researchReport=("Ez egy példa riport.\n\nA Jade AI összesen több mint 300 forrást dolgozott fel több modellszinten, és a legfontosabb, legmegalapozottabb információkat gyűjtötte össze. Itt kellene megjelenjen a minimum 20.000 karakteres, magyar összegzés, amit a Jade AI generált a mély kutatásból.");
      render();
    }
    function showReport(){ document.getElementById('report-modal').classList.add('active'); }
    function closeReport(){ document.getElementById('report-modal').classList.remove('active'); }
    function sendMsg(){
      let textarea = document.getElementById('chat-input');
      let msg = textarea.value.trim(); if(!msg) return;
      chatHistory.push({role:'user',content:msg}); render(); textarea.value="";
      sendToBackend(msg);
    }
    async function sendToBackend(message) {
      // gyors válasz demóban (lokális FastAPI backend http://localhost:7240/chat)
      let resp = await fetch("/chat",{
        method:"POST", headers:{"Content-Type":"application/json"},
        body:JSON.stringify({msg:message,pro:proEnabled})
      });
      let data = await resp.json();
      chatHistory.push({role:'jade',content:data.reply, elapsed:data.elapsed||""});
      render();
    }
    // --- Init
    render();
    window.render=render;window.toggleSidebar=toggleSidebar;window.toggleProMode=toggleProMode;
    window.startNewChat=startNewChat;window.showPlusMenu=showPlusMenu;window.sendMsg=sendMsg;
    window.setExtended=setExtended;window.setResearch=setResearch;window.setImageGen=setImageGen;
    window.setWebsearch=setWebsearch;window.setAttach=setAttach;window.loadChat=loadChat;
    window.searchChat=searchChat;window.toggleTheme=toggleTheme;
    window.showReport=showReport;window.closeReport=closeReport;
  </script>
</body>
</html>


 2. main.py (FastAPI backend)

python
from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from fastapi.middleware.cors import CORSMiddleware

import time
from typing import Dict

app = FastAPI()
app.add_middleware(
    CORSMiddleware,
    allow_origins=['*'],
    allow_methods=['*'],
    allow_headers=['*'],
)

# Demóban minden Jade AI néven jelenik meg. Gyártásra kész helyen pl. OpenAI, Gemini, xAI, ExaAI, Llama hívásokat compositálj!
def jade_reply(msg: str, pro: bool) -> Dict:
    t0 = time.time()
    if pro:
        # mindkét modell összevont választ adunk (de a Jade AI szerepében!)
        # produktív rendszeren: dedikált modellek hívása, pl. /v1/openai, /v1/grok, de sosem írd ki a modell nevét
        answer = (
            "A kérdésedre a következőket találtam:\n\n"
            "Első nézőpont: ... [itt jelenne meg a GPT-4.1 összegzett válasza]\n\n"
            "Második nézőpont: ... [itt jelenne meg a Grok 3 feldolgozott summája]\n\n"
            "A Jade AI mindkét szemléletből kivonatolta a lényeget, hogy teljesebb válasz szülessen."
        )
    else:
        # gyors, pontos válasz (pl. Llama 4 Maverick, fast/settings, minden Jade AI néven!)
        answer = (
            "A Jade AI gyorsválasza:\n"
            "Ez egy példaválasz - a valós rendszer itt egy nagy pontosságú, nagyon gyors Jade AI-féle válasszal szolgál."
        )
    elapsed = f"{int((time.time()-t0)*1000)} ms"
    return {"reply": answer, "elapsed":elapsed}

@app.post("/chat")
async def chat(req: Request):
    data = await req.json()
    msg = data.get("msg","")
    pro = data.get("pro",False)
    return JSONResponse(jade_reply(msg,pro))


Kiegészítések:
 Készíts egy manifest.jsont, favicont. 
 Szükség esetén index.htmlbe <meta name="apple-touch-icon" href="..."> és mobil elérési ikonok.
 A backend /chat végpont az üzeneteket gyártási szintű, gyors valós AI megoldásokkal cserélhető!
 A frontend PWA, teljes képernyőn fut, iOS icon, haptika, natív érzetek (pl. swipe sidebar, tapvibe).
 A válasz minden helyzetben rejtett modellnévvel, kizárólag Jade AI néven jelenik meg.
 Sötét mód azonnali  sidebaron is jól néz ki.

Ez a stack azonnal “indítható” gyártási alapon, magyar felülettel!
